#!/usr/bin/env node

const fs = require('fs');
const path = require('path');

// Function to parse different date formats
function parseDate(dateStr) {
  // Handle DD/MM/YYYY format
  if (dateStr.includes('/')) {
    const parts = dateStr.split('/');
    if (parts.length === 3) {
      const [day, month, year] = parts;
      return `${year}-${month.padStart(2, '0')}-${day.padStart(2, '0')}T00:00:00Z`;
    }
  }

  // Handle ISO format
  if (dateStr.includes('T') || dateStr.includes('-')) {
    return dateStr;
  }

  return dateStr;
}

// Function to parse value with null handling
function parseValue(valueStr) {
  if (!valueStr || valueStr === 'null' || valueStr === 'N/A' || valueStr === '') {
    return 0;
  }
  const parsed = parseFloat(valueStr);
  return isNaN(parsed) ? 0 : parsed;
}

// Function to clean and process CSV data
function processCSV(filePath) {
  const content = fs.readFileSync(filePath, 'utf8');
  const lines = content.split('\n').filter(line => line.trim());

  let events = [];
  let headerSeen = false;

  for (const line of lines) {
    // Remove trailing commas
    const cleanLine = line.replace(/,\s*$/, '');
    const fields = cleanLine.split(',');

    // Skip header rows (including duplicates)
    if (fields[0] === 'event_id') {
      if (headerSeen) continue; // Skip duplicate header
      headerSeen = true;
      continue;
    }

    // Skip empty lines
    if (fields.length < 5) continue;

    // Process the data
    const event = {
      event_id: fields[0],
      event_ts: parseDate(fields[1]),
      user_id: fields[2],
      event_type: fields[3],
      value: parseValue(fields[4])
    };

    events.push(event);
  }

  return events;
}

// Function to send data to Moose ingest endpoint
async function sendToMoose(events) {
  const fetch = (await import('node-fetch')).default;

  for (const event of events) {
    try {
      const response = await fetch('http://localhost:4000/ingest/Event', {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json',
        },
        body: JSON.stringify(event)
      });

      if (!response.ok) {
        console.error(`Failed to send event ${event.event_id}: ${response.status}`);
      } else {
        console.log(`Successfully sent event ${event.event_id}`);
      }
    } catch (error) {
      console.error(`Error sending event ${event.event_id}:`, error.message);
    }
  }
}

async function main() {
  const csvDir = '/data/csv';
  const csvFiles = fs.readdirSync(csvDir).filter(file => file.endsWith('.csv'));

  console.log(`Found ${csvFiles.length} CSV files to process`);

  let allEvents = [];

  for (const file of csvFiles) {
    console.log(`Processing ${file}...`);
    const filePath = path.join(csvDir, file);
    const events = processCSV(filePath);
    allEvents = allEvents.concat(events);
    console.log(`Processed ${events.length} events from ${file}`);
  }

  console.log(`Total events to load: ${allEvents.length}`);

  // Wait a moment for Moose to be ready
  await new Promise(resolve => setTimeout(resolve, 2000));

  await sendToMoose(allEvents);

  console.log('Data loading complete!');
}

main().catch(console.error);

